    private void Mes1_BoxActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_Mes1_BoxActionPerformed
        String Mes= (String) Mes1_Box.getSelectedItem();
    Dia1_Box.removeAllItems();
    switch (Mes) {
        case "01":
        case "03":
        case "05":
        case "07":
        case "08":
        case "10":
        case "12":
            for (int i = 1; i <= 31; i++) {
            Dia1_Box.addItem(String.valueOf(i));
        }
        break;
        case "02":
        for (int i = 1; i <= 28; i++) {
            Dia1_Box.addItem(String.valueOf(i));
        }
        break;
        case "04":
        case "06":
        case "09":
        case "11":
        for (int i = 1; i <= 30; i++) {
            Dia1_Box.addItem(String.valueOf(i));
        }
        break;
    }
    }//GEN-LAST:event_Mes1_BoxActionPerformed

